mapper.update:
UPDATE message_read_status
SET is_read = 1
WHERE chat_room_id = #{chatRoomId}
      AND member_id = #{memberId}

mapper.select:
SELECT COUNT(*)
FROM message_read_status
WHERE chat_room_id = #{chatRoomId}
      AND member_id = #{memberId}
      AND is_read = 0

SELECT *
FROM chat_room
WHERE id IN (
	SELECT cp1.chat_room_id
	FROM chat_participant cp1
	INNER JOIN chat_participant cp2
		ON cp1.chat_room_id = cp2.chat_room_id
	WHERE cp1.member_id = #{memberId}
	  AND cp2.member_id = #{otherMemberId}
	  AND market_no = #{marketNo}
)
AND is_group_chat = 1
